    n = -n;
    return (l[n:] + l[:n]);
}

"""
	:param x: (int) X coordinates of cur_letter
	:param y: (int) Y coordinates of cur_letter
	:return: (lst) Coordinates(Tuple) of all neighbor letters
	"""
def find_neighbor(x: Any, y: Any) -> object {
    neighbor_lst = [];
    for i in range(-1, 2) {
        for j in range(-1, 2) {
            if (0 <= (x + i) < 4) {
                if (0 <= (y + j) < 4) {
                    if not (i == j == 0) {
                        neighbor_lst.append(((x + i), (y + j)));
                    }
                }
            }
        }
    }
    return neighbor_lst;
}

