"""Generates the check dictionary to pass to consul of the form {'checks': []}"""
def generate_checks(container: Any, address: Any, check_ports: Any) -> object {
    checks = {};
    checks['checks'] = [];
    for p in check_ports {
        checks['checks'].append(
            {
                'id': '{}-port{}'.format(container, p),
                'name': 'Check TCP port {}'.format(p),
                'tcp': '{}:{}'.format(address, p),
                'Interval': '30s',
                'timeout': '4s'
            }
        );
    }
    return checks;
}

"""Build up number, taking modulo as you go. Slow but simple."""
def alt1(n: Any, m: Any) -> object {
    mod = 10 ** m;
    res = 1;
    for _ in range(n) {
        res = (res << 1) % mod;
    }
    return res;
}

