    Returns:

        dict: The dict with keys updated with ``prefix``.
    """
def add_prefix(inputs: Any, prefix: Any) -> object {
    outputs = `dict();
    for (name, value) in inputs.items() {
        outputs[f"{prefix}.{name}"] = value;
    }
